import{_ as o,o as t,c as i,a2 as a}from"./chunks/framework.CFOYCmPM.js";const u=JSON.parse('{"title":"Chapter 8: Mod Signing & 1-Click Steam Workshop Publishing","description":"","frontmatter":{},"headers":[],"relativePath":"guide/export-and-publish.md","filePath":"guide/export-and-publish.md","lastUpdated":null}'),r={name:"guide/export-and-publish.md"};function n(s,e,l,d,p,c){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="chapter-8-mod-signing-1-click-steam-workshop-publishing" tabindex="-1">Chapter 8: Mod Signing &amp; 1-Click Steam Workshop Publishing <a class="header-anchor" href="#chapter-8-mod-signing-1-click-steam-workshop-publishing" aria-label="Permalink to &quot;Chapter 8: Mod Signing &amp; 1-Click Steam Workshop Publishing&quot;">​</a></h1><p>When your world and quests are ready, DayZ Studio automates the entire export, cryptographic signing, and publishing pipeline.</p><hr><h2 id="🔍-the-pre-flight-validator-✔-check" tabindex="-1">🔍 The Pre-Flight Validator (<code>✔ Check</code>) <a class="header-anchor" href="#🔍-the-pre-flight-validator-✔-check" aria-label="Permalink to &quot;🔍 The Pre-Flight Validator (`✔ Check`)&quot;">​</a></h2><p>Before packaging your mod, click the <strong>✔ Check</strong> button on the top toolbar.</p><p>DayZ Studio scans your entire project for common pitfalls:</p><ul><li>Disconnected quest or dialogue nodes.</li><li>Invalid or misnamed item classnames.</li><li>Missing voice audio files.</li><li>Excessive prop concentration (exceeding the 150m network bubble density threshold).</li></ul><p>If an issue is found, clicking the warning badge jumps directly to the exact prop or node that requires attention!</p><hr><h2 id="🔐-automated-cryptographic-signing" tabindex="-1">🔐 Automated Cryptographic Signing <a class="header-anchor" href="#🔐-automated-cryptographic-signing" aria-label="Permalink to &quot;🔐 Automated Cryptographic Signing&quot;">​</a></h2><p>Every DayZ server requires mods to be cryptographically signed to prevent file tampering.</p><ul><li>DayZ Studio automatically generates your private key (<code>.biprivatekey</code>) and public key (<code>.bikey</code>) inside <code>Documents\\DayZStudio\\Keys</code>.</li><li>When you export, DayZ Studio communicates directly with <strong>DayZ Tools</strong> to binarize configs and sign your <code>.pbo</code> archive.</li></ul><hr><h2 id="📦-export-options" tabindex="-1">📦 Export Options <a class="header-anchor" href="#📦-export-options" aria-label="Permalink to &quot;📦 Export Options&quot;">​</a></h2><h3 id="option-a-standalone-server-zip-package" tabindex="-1">Option A: Standalone Server ZIP Package <a class="header-anchor" href="#option-a-standalone-server-zip-package" aria-label="Permalink to &quot;Option A: Standalone Server ZIP Package&quot;">​</a></h3><p>Click <strong>⇩ Export</strong> ➔ <strong>Export Server Package (.zip)</strong>.</p><p>Studio compiles a clean, production-ready archive containing:</p><ol><li><code>@YourMod/Addons/yourmod.pbo</code> (The compiled, signed mod).</li><li><code>keys/yourmod.bikey</code> (The public key for the server host).</li><li><code>INSTALL.txt</code> (Clear instructions for server owners on adding <code>-mod=@YourMod</code> to their startup line).</li></ol><h3 id="option-b-1-click-steam-workshop-publishing" tabindex="-1">Option B: 1-Click Steam Workshop Publishing <a class="header-anchor" href="#option-b-1-click-steam-workshop-publishing" aria-label="Permalink to &quot;Option B: 1-Click Steam Workshop Publishing&quot;">​</a></h3><p>Click <strong>File ▸ ☁ Publish to Steam Workshop…</strong>:</p><ol><li>Studio connects directly to your active Steam client.</li><li>It auto-generates a first-draft description, title, preview thumbnail, and tags from your project.</li><li>Click <strong>Upload to Steam Workshop</strong>.</li><li>Your mod is compiled, signed, and uploaded to the Steam Workshop automatically!</li><li>For future updates, reopen this menu, enter your changelog notes, and click <strong>Update</strong>!</li></ol><hr><h2 id="👥-how-players-join-your-server" tabindex="-1">👥 How Players Join Your Server <a class="header-anchor" href="#👥-how-players-join-your-server" aria-label="Permalink to &quot;👥 How Players Join Your Server&quot;">​</a></h2><p>Because DayZ Studio creates <strong>100% vanilla-compatible mods</strong>, players only need your mod! They do not need to download Community Framework (CF), Dabs Framework, DayZ Expansion, or any other third-party dependencies just to play your content.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Already running CF or Expansion?</strong> If your server already uses Community Framework, Dabs Framework, or DayZ Expansion, DayZ Studio mods coexist with them harmoniously. They are not required, but they are 100% supported.</p></div>',25)])])}const g=o(r,[["render",n]]);export{u as __pageData,g as default};
